QCU_T("es", "abordaje", {
  "0": ["El dolor: señala la respuesta correcta",["La noradrenalina es un neurotransmisor que facilita la transmisión del dolor","La palestesia es una sensibilidad superficial asociada a las vibraciones óseas","El dolor neuropático es una afectación nerviosa indirecta","Todas las respuestas son falsas"],["Correcto: actúa a través de los receptores alfa-1 y beta postsinápticos, que son excitadores; solo los alfa-2 presinápticos son inhibidores.","Falso: la palestesia es una sensibilidad profunda y, además, no es la respuesta que se busca aquí.","Falso: el dolor neuropático se debe a una lesión o una enfermedad del propio sistema somatosensorial.","Falso: la primera opción sí es correcta."]],
  "1": ["¿Cuál de estos neurotransmisores no inhibe el dolor?",["Glutamato","Serotonina y noradrenalina","GABA","Opioides"],["Correcto: el glutamato es el neurotransmisor excitador más abundante del sistema nervioso.","Falso: ambas participan en las vías inhibidoras descendentes.","Falso: el GABA es el principal neurotransmisor inhibidor.","Falso: los péptidos opioides endógenos son inhibidores."]],
  "2": ["Acerca de la sustancia P:",["Facilita el dolor","Inhibe el dolor","No actúa sobre el dolor","Actúa únicamente sobre el dolor agudo"],["Correcto: interviene en el dolor lento y crónico y en la inflamación neurógena.","Falso: es un neurotransmisor excitador, no inhibidor.","Falso: su papel en la nocicepción es, al contrario, fundamental.","Falso: interviene sobre todo en el dolor lento y crónico."]],
  "3": ["¿Qué ganglio se encarga de la sensibilidad somática de la cabeza y de la cara?",["El ganglio trigeminal","El ganglio de la raíz dorsal","El ganglio nodoso del vago","El ganglio cervical superior"],["Correcto: el ganglio de la raíz dorsal se encarga de la sensibilidad del resto del cuerpo.","Falso: inerva el resto del cuerpo, no la cara.","Falso: participa en la sensibilidad visceral.","Falso: es un relevo simpático, no sensitivo."]],
  "4": ["¿Qué fibra nociceptiva está mielinizada y conduce el dolor rápido?",["La fibra A delta","La fibra C","La fibra A beta","La fibra A alfa"],["Correcto: la fibra C, amielínica, conduce lentamente un dolor difuso de tipo quemazón.","Falso: no está mielinizada y conduce lentamente.","Falso: está mielinizada, pero transmite el tacto, no la nocicepción.","Falso: transmite la propiocepción y la motricidad."]],
  "5": ["¿Qué proporción de las aferencias nociceptivas que llegan a la médula viaja por las fibras C?",["Alrededor del setenta por ciento","Alrededor del diez por ciento","Alrededor del treinta por ciento","Alrededor del noventa y cinco por ciento"],["Correcto: estas fibras amielínicas, de menos de dos micrómetros, son polimodales.","Falso: esta estimación queda muy por debajo de su proporción real.","Falso: la proporción real es bastante mayor.","Falso: esta proporción está sobrestimada."]],
  "6": ["¿Qué significa que una fibra C sea polimodal?",["Que responde al calor, a lo mecánico y a lo químico","Que conduce el impulso en los dos sentidos","Que cambia de velocidad de conducción según la temperatura","Que inerva varios metámeros a la vez"],["Correcto: esta convergencia explica el carácter difuso del dolor que transmite.","Falso: no es eso lo que designa el término polimodal.","Falso: la polimodalidad se refiere a la naturaleza de los estímulos.","Falso: la polimodalidad no describe la distribución territorial."]],
  "7": ["¿Cuál es el potencial de reposo de una neurona?",["Alrededor de menos setenta milivoltios","Alrededor de menos cincuenta y cinco milivoltios","Alrededor de más cuarenta milivoltios","Alrededor de cero milivoltios"],["Correcto: el umbral de disparo se sitúa en torno a menos cincuenta y cinco milivoltios.","Falso: ese valor corresponde al umbral de disparo.","Falso: ese valor corresponde al pico del potencial de acción.","Falso: la neurona en reposo está polarizada negativamente."]],
  "8": ["¿Qué canal se encarga de la despolarización durante un potencial de acción?",["El canal de sodio dependiente de voltaje","El canal de potasio dependiente de voltaje","La bomba de sodio-potasio","El canal de cloro del receptor GABA"],["Correcto: la repolarización corre a cargo de los canales de potasio dependientes de voltaje.","Falso: se encarga de la repolarización.","Falso: restablece los gradientes, pero no despolariza.","Falso: su apertura es, al contrario, inhibidora."]],
  "9": ["¿Qué receptor se activa con el calor, los protones y la capsaicina?",["El receptor TRPV1","El receptor TRPA1","El canal ASIC","El canal Piezo"],["Correcto: el TRPA1 responde a los irritantes, a las toxinas y al frío intenso.","Falso: responde a los irritantes y al frío intenso.","Falso: lo activan únicamente los protones.","Falso: es mecanosensible."]],
  "10": ["¿Qué canal se encarga de la mecanotransducción?",["El canal Piezo","El receptor TRPV1","El canal ASIC","El canal de calcio dependiente de voltaje"],["Correcto: traduce la deformación mecánica en una señal eléctrica.","Falso: responde al calor y a la capsaicina.","Falso: lo activa la acidez.","Falso: se encarga de la liberación de los neurotransmisores."]],
  "11": ["¿Cuál es el papel de los canales de calcio dependientes de voltaje en la sinapsis?",["Permitir la liberación de los neurotransmisores","Despolarizar la membrana del axón","Repolarizar la membrana tras el pico","Hiperpolarizar la membrana postsináptica"],["Correcto: la entrada de calcio desencadena la fusión de las vesículas presinápticas.","Falso: esa despolarización corresponde a los canales de sodio.","Falso: esa función corresponde a los canales de potasio.","Falso: esa inhibición pasa por los canales de cloro."]],
  "12": ["¿Qué hace falta, además del glutamato, para activar el receptor NMDA?",["Glicina","GABA","Sustancia P","Noradrenalina"],["Correcto: este correceptor es indispensable para la apertura del canal.","Falso: el GABA es inhibidor y actúa sobre otros receptores.","Falso: actúa sobre los receptores de taquicininas.","Falso: actúa sobre los receptores adrenérgicos."]],
  "13": ["¿Qué fenómeno hace posible el receptor NMDA?",["El wind-up y la potenciación a largo plazo","La inhibición descendente del tronco del encéfalo","El cierre de los canales de sodio","La hiperpolarización de la membrana"],["Correcto: la entrada de calcio genera una hiperexcitabilidad postsináptica duradera.","Falso: esa inhibición discurre por otras vías.","Falso: no es ese el mecanismo implicado.","Falso: el NMDA es excitador, no inhibidor."]],
  "14": ["¿Qué ion entra cuando se activan los receptores GABA-A y de glicina?",["El cloro","El calcio","El sodio","El potasio"],["Correcto: su entrada hiperpolariza la célula y produce la inhibición.","Falso: su entrada es excitadora y se produce por otros canales.","Falso: su entrada despolariza la membrana.","Falso: es su salida la que repolariza la membrana."]],
  "15": ["¿A qué proteína G están acoplados los receptores opioides y cannabinoides?",["A la proteína Gi","A la proteína Gq","A la proteína Gs","A ninguna proteína G, son canales iónicos"],["Correcto: inhiben la adenilato ciclasa y reducen el AMP cíclico, de ahí su efecto inhibidor.","Falso: esa proteína está acoplada a los receptores de taquicininas, que son excitadores.","Falso: al contrario, estimularía la adenilato ciclasa.","Falso: son receptores metabotrópicos."]],
  "16": ["¿Qué vía de señalización siguen los receptores de las taquicininas?",["La vía Gq, fosfolipasa C y proteína cinasa C","La vía Gi, con una inhibición intensa de la adenilato ciclasa","Una vía ionotrópica directa","Una vía que pasa por el receptor NMDA"],["Correcto: esta vía es excitadora, al contrario que los receptores acoplados a Gi.","Falso: esa vía es la de los receptores opioides y cannabinoides.","Falso: los receptores de taquicininas son metabotrópicos.","Falso: el NMDA es un receptor ionotrópico distinto."]],
  "17": ["¿Qué receptores adrenérgicos son inhibidores en la modulación del dolor?",["Los receptores alfa-2 presinápticos","Los receptores alfa-1 postsinápticos","Los receptores beta postsinápticos","Los receptores alfa-2 postsinápticos"],["Correcto: los alfa-1 y los beta postsinápticos son, al contrario, excitadores.","Falso: son excitadores.","Falso: también son excitadores.","Falso: es su localización presináptica la que determina el efecto inhibidor."]],
  "18": ["¿Cuál es el neurotransmisor excitador más abundante del sistema nervioso?",["El glutamato","La sustancia P","La noradrenalina","La serotonina"],["Correcto: la sustancia P y el péptido relacionado con el gen de la calcitonina también son excitadores.","Falso: es excitadora, pero mucho menos abundante.","Falso: su acción excitadora pasa por receptores específicos y es limitada.","Falso: su acción excitadora pasa por el receptor 5-HT3 y es minoritaria."]],
  "19": ["¿Qué efecto vascular produce la sustancia P?",["Una vasodilatación con extravasación","Una vasoconstricción con isquemia","Una trombosis de los capilares","Ningún efecto vascular en particular"],["Correcto: es el mecanismo de la inflamación neurógena.","Falso: el efecto es vasodilatador.","Falso: no se describe ningún efecto trombótico.","Falso: su papel vascular es, al contrario, central."]],
  "20": ["¿Qué péptido de las fibras C está implicado en la migraña?",["El péptido relacionado con el gen de la calcitonina","La glicina del asta dorsal","El GABA de las interneuronas espinales","El óxido nítrico difusible local"],["Correcto: es vasodilatador y actúa a través del complejo CALCRL y RAMP1.","Falso: es un neurotransmisor inhibidor.","Falso: es inhibidor y no está implicado de ese modo.","Falso: es difusible y activa el receptor NMDA, pero no es el péptido descrito."]],
  "21": ["¿A través de qué receptor ejerce la serotonina un efecto excitador?",["A través del receptor 5-HT3","A través del receptor 5-HT1","A través del receptor NMDA","A través del receptor GABA-A"],["Correcto: es el único receptor serotoninérgico de tipo ionotrópico.","Falso: no es ese el receptor que media este efecto.","Falso: ese receptor responde al glutamato.","Falso: ese receptor es inhibidor."]],
  "22": ["¿Qué mecanismo inhibidor se propone en el dolor crónico?",["La desinhibición gabaérgica","La potenciación gabaérgica","La destrucción de los receptores NMDA","La sobreexpresión de los canales de cloro"],["Correcto: explica, entre otras cosas, la alodinia mecánica tras una lesión nerviosa.","Falso: un refuerzo de la inhibición aliviaría el dolor.","Falso: ese mecanismo no está descrito.","Falso: reforzaría la inhibición."]],
  "23": ["¿Qué gas difusible activa el receptor NMDA?",["El óxido nítrico","El monóxido de carbono","El dióxido de carbono","El sulfuro de hidrógeno"],["Correcto: figura entre los mediadores inhibidores, junto con el GABA y los opioides endógenos.","Falso: no es el mediador que se describe aquí.","Falso: no interviene en esta modulación.","Falso: no se cita en este contexto."]],
  "24": ["¿Cuáles son las tres etapas de la nocicepción?",["Transducción, transmisión, modulación","Absorción, distribución, eliminación","Sensibilización, inhibición, habituación","Recepción, integración, proyección"],["Correcto: la transducción convierte el estímulo en señal eléctrica, a través de TRPV1 o Piezo.","Falso: esa secuencia corresponde a la farmacocinética.","Falso: esos conceptos no forman la secuencia descrita.","Falso: esa serie no corresponde a la terminología establecida."]],
  "25": ["¿A partir de qué temperatura se activan los nociceptores térmicos de calor?",["Por encima de cuarenta y dos grados","Por encima de treinta y siete grados","Por encima de cincuenta grados","Por encima de sesenta grados"],["Correcto: los nociceptores de frío se activan por debajo de cinco grados.","Falso: esa temperatura es la del cuerpo en reposo.","Falso: ese umbral es demasiado alto.","Falso: ese umbral provocaría ya una quemadura profunda."]],
  "26": ["¿Qué sustancia activa los nociceptores químicos?",["La bradicinina","El GABA","La glicina","La encefalina"],["Correcto: la histamina, las prostaglandinas y la capsaicina actúan de la misma manera.","Falso: es inhibidor y no activa los nociceptores.","Falso: también es inhibidora.","Falso: es un péptido opioide endógeno y, por tanto, inhibidor."]],
  "27": ["¿Qué es un nociceptor silente?",["Un receptor que se activa una vez instaurada la inflamación","Un receptor que nunca se activa","Un receptor que responde a todos los estímulos","Un receptor presente únicamente en la piel lampiña"],["Correcto: desempeña un papel importante en el dolor crónico.","Falso: se activa tardíamente, pero se activa.","Falso: esa descripción corresponde al nociceptor polimodal.","Falso: la localización no define este tipo de receptor."]],
  "28": ["¿En qué estructura son especialmente numerosos los nociceptores polimodales?",["La pulpa dental","El periostio de los huesos largos","La cápsula articular de la rodilla","El tejido adiposo subcutáneo"],["Correcto: esa densidad explica las características del dolor dental.","Falso: no es esa la estructura citada.","Falso: no se menciona por este motivo.","Falso: es pobre en terminaciones nociceptivas."]],
  "29": ["¿En qué capas del asta dorsal terminan las fibras A delta?",["En las capas I y V","En las capas I y II","En las capas III y IV","En las capas VII y VIII"],["Correcto: las fibras C terminan en las capas I y II.","Falso: esa terminación corresponde a las fibras C.","Falso: esas capas reciben sobre todo aferencias no nociceptivas.","Falso: esas capas son motoras e intermedias."]],
  "30": ["¿Hacia qué núcleo talámico proyecta la vía espinotalámica lateral?",["Hacia el núcleo ventral posterolateral","Hacia el tálamo medial","Hacia el hipotálamo lateral posterior","Hacia el núcleo caudado"],["Correcto: transmite el componente sensorial-discriminativo, es decir, la localización y la gravedad.","Falso: esa proyección corresponde a la vía anterior.","Falso: no es la diana de esta vía.","Falso: esa estructura no es un relevo de la vía espinotalámica."]],
  "31": ["¿Qué componente del dolor transmite la vía espinotalámica anterior?",["El componente emocional desagradable","La localización precisa del estímulo","La valoración de la intensidad del estímulo","La discriminación entre dos puntos"],["Correcto: la vía lateral transmite, en cambio, el componente sensorial-discriminativo.","Falso: esa información viaja por la vía lateral.","Falso: esa valoración también corresponde a la vía lateral.","Falso: esa función corresponde a los cordones posteriores."]],
  "32": ["¿Qué núcleo del tronco del encéfalo proyecta hacia la amígdala y regula el dolor neuropático?",["El núcleo parabraquial","La sustancia gris periacueductal","El núcleo rojo","El núcleo de Edinger-Westphal"],["Correcto: la sustancia gris periacueductal, por su parte, se encarga de la modulación descendente.","Falso: es el centro de la modulación descendente.","Falso: pertenece al sistema motor.","Falso: se encarga de la inervación pupilar parasimpática."]],
  "33": ["¿Qué estructura es el centro de la modulación descendente del dolor?",["La sustancia gris periacueductal","El núcleo parabraquial","El tálamo ventral posterolateral","La corteza somatosensorial primaria"],["Correcto: actúa junto con la formación reticular sobre los relevos medulares.","Falso: proyecta hacia la amígdala y regula el dolor neuropático.","Falso: es un relevo ascendente sensorial.","Falso: recibe la información, pero no es ese centro."]],
  "34": ["¿Cuál es la velocidad de conducción aproximada de una fibra C?",["Alrededor de dos micrómetros por segundo","Alrededor de cincuenta metros por segundo","Alrededor de veinte metros por segundo","Alrededor de cien metros por segundo"],["Correcto: esa lentitud explica el segundo dolor, difuso y quemante.","Falso: esa velocidad corresponde a las fibras mielínicas gruesas.","Falso: esa velocidad corresponde a las fibras A delta.","Falso: esa velocidad corresponde a las fibras A alfa."]],
  "35": ["¿Qué diámetro caracteriza a una fibra C?",["Menos de dos micrómetros","Alrededor de diez micrómetros","Alrededor de veinte micrómetros","Alrededor de cincuenta micrómetros"],["Correcto: su pequeño calibre y la ausencia de mielina explican su lentitud.","Falso: ese calibre corresponde a las fibras A delta.","Falso: ese calibre corresponde a las fibras mielínicas gruesas.","Falso: ninguna fibra nerviosa alcanza ese calibre."]],
  "36": ["¿Qué canal iónico se activa con los protones?",["El canal ASIC","El canal Piezo","El receptor TRPA1","El canal de cloro del receptor de glicina"],["Correcto: su propio nombre remite a su sensibilidad a la acidez.","Falso: es mecanosensible.","Falso: responde a los irritantes y al frío intenso.","Falso: es inhibidor y responde a la glicina."]],
  "37": ["¿Qué péptidos opioides endógenos modulan el dolor?",["Encefalinas, dinorfina y endorfinas","Sustancia P, glutamato y calcitonina","Bradicinina, histamina y prostaglandinas","Noradrenalina, serotonina y dopamina"],["Correcto: actúan sobre los receptores opioides acoplados a proteínas Gi.","Falso: esos mediadores son excitadores.","Falso: son mediadores de la inflamación y activan los nociceptores.","Falso: son monoaminas y no péptidos opioides."]],
  "38": ["¿Qué receptor opioide designa la abreviatura MOR?",["El receptor mu","El receptor delta","El receptor kappa","El receptor cannabinoide de tipo 1"],["Correcto: DOR designa el receptor delta y KOR el receptor kappa.","Falso: le corresponde la abreviatura DOR.","Falso: le corresponde la abreviatura KOR.","Falso: le corresponde la abreviatura CB1."]],
  "39": ["¿Qué tipo de neurona conecta dos neuronas entre sí dentro del sistema nervioso?",["La interneurona","La neurona sensitiva","La neurona motora","La neurona posganglionar"],["Correcto: la neurona sensitiva es aferente y la motora, eferente.","Falso: es aferente y conduce la información hacia el centro.","Falso: es eferente y gobierna el efector.","Falso: pertenece al sistema autónomo."]],
  "40": ["¿Qué parte de la neurona recibe la información de las demás células?",["Las dendritas","El axón","Solo el cuerpo celular","La vaina de mielina"],["Correcto: el axón, en cambio, conduce el impulso hacia las células siguientes.","Falso: conduce el impulso hacia la salida de la neurona.","Falso: integra la información, pero no es su vía principal de entrada.","Falso: acelera la conducción sin recibir la información."]],
  "41": ["¿Cómo recupera la membrana su potencial de reposo tras un potencial de acción?",["Mediante la bomba de sodio-potasio","Mediante la apertura de los canales de sodio","Mediante la entrada masiva de calcio","Mediante el cierre de los canales de cloro"],["Correcto: restablece los gradientes iónicos tras la hiperpolarización transitoria.","Falso: esa apertura produce la despolarización.","Falso: desencadena la liberación de los neurotransmisores.","Falso: no es ese el mecanismo de retorno al reposo."]],
  "42": ["¿Cuál es el valor del pico de un potencial de acción?",["Alrededor de más cuarenta milivoltios","Alrededor de menos cincuenta y cinco milivoltios","Alrededor de menos setenta milivoltios","Alrededor de más cien milivoltios"],["Correcto: se parte de menos setenta y el umbral se sitúa en menos cincuenta y cinco.","Falso: ese valor corresponde al umbral de disparo.","Falso: ese valor corresponde al reposo.","Falso: ese valor supera con mucho el pico real."]],
  "43": ["¿Qué receptor responde a los irritantes, a las toxinas y al frío intenso?",["El receptor TRPA1","El receptor TRPV1","El canal ASIC","El canal Piezo"],["Correcto: el TRPV1 responde al calor, a los protones y a la capsaicina.","Falso: responde al calor y a la capsaicina.","Falso: responde específicamente a los protones.","Falso: es mecanosensible."]],
  "44": ["¿Cuál es la definición del sistema nervioso periférico?",["Los nervios y ganglios situados fuera del neuroeje","Únicamente el conjunto de los nervios craneales","La médula espinal y sus raíces","Únicamente el conjunto de las vías autónomas"],["Correcto: comprende una vertiente somatosensorial y una vertiente visceral.","Falso: esa definición es muy restrictiva.","Falso: la médula pertenece al sistema nervioso central.","Falso: la vertiente somática también forma parte de él."]],
  "45": ["¿Cuál es la definición actual del dolor?",["Una experiencia sensorial y emocional desagradable","Una sensación desagradable debida a una lesión tisular real","La activación de los nociceptores por un estímulo nocivo intenso","Una respuesta refleja de retirada ante una agresión"],["Correcto: la mención «o semejante a» permite incluir los dolores sin lesión identificable.","Falso: la definición ya no exige una lesión real.","Falso: esa definición corresponde a la nocicepción, no al dolor.","Falso: el reflejo de retirada no define la experiencia dolorosa."]],
  "46": ["¿Qué precisa la definición actual del dolor acerca de la nocicepción?",["Que dolor y nocicepción no son lo mismo","Que dolor y nocicepción son dos términos equivalentes","Que la nocicepción supone siempre un dolor percibido","Que el dolor supone siempre una nocicepción activa"],["Correcto: el dolor es siempre subjetivo, y todo relato de dolor debe ser aceptado.","Falso: la distinción entre ambos es, al contrario, esencial.","Falso: puede haber nocicepción sin dolor percibido.","Falso: puede haber dolor sin nocicepción."]],
  "47": ["¿Qué es la hiperalgesia?",["Un dolor aumentado frente a un estímulo nociceptivo","Un dolor frente a un estímulo no nociceptivo","Un dolor disminuido frente a un estímulo nociceptivo","Una sensación anómala pero no desagradable"],["Correcto: la alodinia, en cambio, es un dolor provocado por un estímulo no nociceptivo.","Falso: esa definición corresponde a la alodinia.","Falso: esa definición corresponde a la hipoalgesia.","Falso: esa definición corresponde a la parestesia."]],
  "48": ["¿Qué refleja una hiperalgesia primaria?",["Una sensibilización periférica en la zona lesionada","Una sensibilización central fuera de la zona lesionada","Una alteración aislada de la inhibición descendente","Una percepción dolorosa de un estímulo táctil"],["Correcto: el umbral desciende y aumenta la reactividad de las fibras A delta y C.","Falso: esa descripción corresponde a la hiperalgesia secundaria.","Falso: ese mecanismo participa en la hiperalgesia secundaria.","Falso: esa descripción corresponde a la alodinia."]],
  "49": ["¿Dónde se localiza una hiperalgesia secundaria?",["Fuera de la zona lesionada","Estrictamente en el lugar de la lesión","En un territorio exclusivamente visceral","Únicamente en el lado contrario a la lesión"],["Correcto: refleja la sensibilización central y la alteración de la inhibición descendente.","Falso: esa localización define la hiperalgesia primaria.","Falso: la localización visceral no entra en esta distinción.","Falso: la lateralidad no es el criterio que se aplica."]],
  "50": ["¿Qué mecanismo explica la alodinia mecánica?",["Las aferencias táctiles A beta se vuelven dolorosas","Las fibras C se mielinizan","Los nociceptores desaparecen por completo de la zona","El umbral de las fibras A delta aumenta"],["Correcto: las interneuronas sensibilizadas dejan pasar esas aferencias hacia las vías nociceptivas.","Falso: no se produce ninguna transformación de ese tipo.","Falso: la desaparición de los nociceptores produciría lo contrario.","Falso: lo que ocurre es un descenso del umbral."]],
  "51": ["¿Qué es la hiperpatía?",["Una respuesta exagerada, persistente o retardada","Un dolor aumentado frente a un estímulo nociceptivo","Un dolor frente a un estímulo no nociceptivo","Una sensación anómala y desagradable"],["Correcto: se observa sobre todo cuando el estímulo es repetitivo.","Falso: esa definición corresponde a la hiperalgesia.","Falso: esa definición corresponde a la alodinia.","Falso: esa definición corresponde a la disestesia."]],
  "52": ["¿Qué es la sensibilización?",["Una respuesta aumentada frente a un estímulo normal","Una respuesta disminuida frente a un estímulo nociceptivo","Un dolor que persiste más de seis meses","Una sensación anómala no desagradable"],["Correcto: es un mecanismo, que no debe confundirse con la cronicidad, que es una duración.","Falso: esa descripción corresponde a la hipoalgesia.","Falso: esa definición corresponde al dolor crónico.","Falso: esa definición corresponde a la parestesia."]],
  "53": ["¿Qué distingue una disestesia de una parestesia?",["La disestesia es desagradable; la parestesia, no","La disestesia es indolora y la parestesia, dolorosa","La disestesia es espontánea y la parestesia, provocada","La disestesia es central y la parestesia, periférica"],["Correcto: la parestesia se atribuye a una actividad anómala no nociceptiva de las fibras A beta.","Falso: los dos calificativos están invertidos.","Falso: no es ese el criterio de distinción establecido.","Falso: la localización no sustenta esta distinción."]],
  "54": ["¿A qué fibras se atribuyen las parestesias?",["A las fibras A beta, por actividad anómala","A las fibras C, por un aumento de la actividad nociceptiva","A las fibras A delta, por actividad nociceptiva rápida","A las fibras simpáticas posganglionares"],["Correcto: es lo que explica su carácter no doloroso.","Falso: esa actividad produciría una sensación dolorosa.","Falso: esas fibras transmiten el dolor rápido.","Falso: no están implicadas en este fenómeno."]],
  "55": ["¿Qué es la hipoestesia?",["Una sensación disminuida, no dolorosa","Un dolor disminuido frente a un estímulo nociceptivo","Una sensación anómala y desagradable","Una ausencia total de cualquier sensación"],["Correcto: la hiperestesia es, al contrario, una sensación aumentada.","Falso: esa definición corresponde a la hipoalgesia.","Falso: esa definición corresponde a la disestesia.","Falso: la abolición completa es la anestesia."]],
  "56": ["¿Qué estructuras componen la red de la saliencia?",["La ínsula anterior y la corteza cingulada","Únicamente la corteza prefrontal dorsolateral","La corteza somatosensorial primaria","El tálamo y los núcleos grises centrales"],["Correcto: esta red prioriza la información, mientras que la red por defecto sostiene el concepto de uno mismo.","Falso: esa región pertenece a la red ejecutiva central.","Falso: procesa la información sensorial, fuera de esta red.","Falso: esas estructuras no definen esta red."]],
  "57": ["¿Qué relación une las tres redes en el sujeto sano?",["Saliencia y ejecutiva correlacionadas, anticorrelacionadas con la red por defecto","Las tres redes están correlacionadas entre sí","Las tres redes son independientes entre sí","La red por defecto está correlacionada con la ejecutiva central"],["Correcto: el dolor crónico hace perder esa anticorrelación.","Falso: esa configuración no corresponde al sujeto sano.","Falso: sus relaciones están, al contrario, estructuradas.","Falso: están anticorrelacionadas en el sujeto sano."]],
  "58": ["¿Qué se observa en el dolor crónico según el modelo de la triple red?",["Pérdida de la anticorrelación y dolor integrado en el yo","Un claro refuerzo de la anticorrelación entre las redes","Una desaparición completa de la red de la saliencia","Una desconexión de la corteza somatosensorial primaria"],["Correcto: a ello se añade una hiperconectividad entre la corteza somatosensorial primaria y la red por defecto.","Falso: lo que se observa es una pérdida de esa anticorrelación.","Falso: la red persiste; solo cambian sus relaciones.","Falso: lo que aparece es, al contrario, una hiperconectividad."]],
  "59": ["¿Qué modelo constituye hoy el estándar clínico en el abordaje del dolor?",["El modelo biopsicosocial","El modelo biomédico clásico","El modelo del organismo maduro","El modelo enactivo de las affordances"],["Correcto: ha sustituido al modelo puramente biomédico.","Falso: precisamente ha quedado superado.","Falso: es un modelo explicativo entre otros, no el estándar clínico.","Falso: se propone, pero no constituye el estándar clínico."]],
  "60": ["¿Qué propone el modelo enactivo del dolor?",["Que el dolor emerge de la interacción entre persona y entorno","Que el dolor es el reflejo directo de una lesión tisular","Que el dolor resulta de una jerarquía de redes cerebrales","Que el dolor se explica solo por las creencias del paciente"],["Correcto: introduce el concepto de affordances.","Falso: esa concepción pertenece al modelo biomédico.","Falso: esa concepción corresponde al modelo de la triple red.","Falso: el modelo no se reduce a las creencias."]],
  "61": ["¿Cómo se define un dolor nociceptivo?",["Por una lesión real o potencial de tejidos no nerviosos","Por una lesión del sistema somatosensorial","Por una nocicepción alterada sin prueba de lesión","Por la superposición de varios mecanismos"],["Correcto: resulta de la activación de los nociceptores.","Falso: esa definición corresponde al dolor neuropático.","Falso: esa definición corresponde al dolor nociplástico.","Falso: esa situación define el dolor mixto."]],
  "62": ["¿Cómo se define un dolor nociplástico?",["Por una nocicepción alterada sin lesión ni enfermedad","Por una lesión real de tejidos no nerviosos","Por una lesión del sistema somatosensorial","Por un dolor que persiste mucho más de seis meses"],["Correcto: no lo explican ni una lesión tisular ni una enfermedad somatosensorial.","Falso: esa definición corresponde al dolor nociceptivo.","Falso: esa definición corresponde al dolor neuropático.","Falso: esa definición corresponde al dolor crónico."]],
  "63": ["¿Qué distingue una neuropatía de un dolor neuropático?",["La neuropatía es una pérdida objetiva de función","La neuropatía proviene de descargas ectópicas","La neuropatía produce síntomas positivos","La neuropatía es siempre dolorosa"],["Correcto: produce signos negativos, mientras que el dolor neuropático proviene de descargas ectópicas.","Falso: ese mecanismo explica el dolor neuropático.","Falso: los signos positivos caracterizan al dolor neuropático.","Falso: puede ser puramente deficitaria."]],
  "64": ["¿Qué fibras explora el electromiograma?",["Las fibras A beta","Las fibras A delta","Las fibras C amielínicas","Todas las fibras sensitivas por igual"],["Correcto: no documenta las fibras A delta y suele ser normal en las neuropatías de fibra fina.","Falso: la prueba no las documenta.","Falso: también quedan fuera del alcance de la prueba.","Falso: la prueba es selectiva de las fibras mielínicas gruesas."]],
  "65": ["¿Qué fibras están afectadas en una neuropatía de fibra fina?",["Las fibras A delta y C","Las fibras A beta y A alfa","Exclusivamente las fibras motoras","Las fibras simpáticas preganglionares"],["Correcto: el electromiograma suele ser normal, de ahí que se recurra a la densidad intraepidérmica.","Falso: esas son las fibras mielínicas gruesas.","Falso: la afectación es sensitiva y autonómica.","Falso: no definen esta entidad."]],
  "66": ["¿Qué prueba explora una neuropatía de fibra fina?",["La densidad intraepidérmica de fibras","El electromiograma convencional","La resonancia magnética medular","Los potenciales evocados visuales"],["Correcto: el electromiograma suele quedarse corto en esta situación.","Falso: explora las fibras gruesas y suele ser normal.","Falso: no explora las fibras periféricas.","Falso: exploran la vía óptica."]],
  "67": ["¿Qué define un dolor crónico?",["Su persistencia más allá de la curación, de tres a seis meses","Una respuesta aumentada frente a un estímulo por debajo del umbral","Un dolor desproporcionado respecto al estímulo","Una ausencia completa de lesión tisular identificable"],["Correcto: es una duración, que no debe confundirse con la sensibilización central, que es un mecanismo.","Falso: esa definición corresponde a la sensibilización central.","Falso: la desproporción es un criterio de orientación, no la definición.","Falso: la ausencia de lesión no entra en la definición de cronicidad."]],
  "68": ["¿Cuál es la primera pregunta del algoritmo de clasificación de un dolor musculoesquelético?",["¿Explica un dolor neuropático el cuadro?","¿Es el dolor desproporcionado?","¿Es el dolor difuso?","¿Supera el inventario de sensibilización los cuarenta puntos?"],["Correcto: después vienen la desproporción, el carácter difuso y el inventario de sensibilización central.","Falso: es la segunda pregunta del algoritmo.","Falso: es la tercera pregunta.","Falso: es la cuarta pregunta."]],
  "69": ["¿Qué criterios bastan para clasificar un dolor como nociplástico en este algoritmo?",["Los criterios uno y tres","Solo los criterios dos y cuatro","Los cuatro criterios son siempre necesarios","Basta únicamente el criterio cuatro"],["Correcto: la ausencia de explicación neuropática junto con el carácter difuso es suficiente.","Falso: no son esos los dos criterios suficientes establecidos.","Falso: bastan dos de ellos.","Falso: el inventario por sí solo no basta."]],
  "70": ["¿Qué punto de corte se aplica al cuestionario DN4?",["Cuatro sobre diez","Doce sobre diez","Siete sobre diez","Cuarenta sobre cien"],["Correcto: el cuestionario de dolor neuropático aplica, en cambio, un punto de corte de doce.","Falso: ese punto de corte pertenece al cuestionario de dolor neuropático.","Falso: ese punto de corte corresponde al índice de dolor generalizado.","Falso: ese punto de corte corresponde al inventario de sensibilización central."]],
  "71": ["¿Qué punto de corte se aplica al inventario de sensibilización central?",["Cuarenta","Veinte","Sesenta","Cuatro"],["Correcto: de treinta a treinta y nueve la afectación es leve, y de cuarenta a cuarenta y nueve, moderada.","Falso: ese punto de corte es demasiado bajo.","Falso: esa cifra corresponde al inicio de la categoría extrema.","Falso: ese punto de corte corresponde al cuestionario DN4."]],
  "72": ["¿A qué categoría corresponde un inventario de sensibilización central de cincuenta y cinco?",["Grave","Leve","Moderada","Extrema"],["Correcto: el intervalo de cincuenta a cincuenta y nueve corresponde al grado grave.","Falso: esa categoría va de treinta a treinta y nueve.","Falso: esa categoría va de cuarenta a cuarenta y nueve.","Falso: esa categoría empieza en sesenta."]],
  "73": ["¿Qué duración mínima exigen los criterios del dolor nociplástico?",["Tres meses","Un mes","Seis meses","Doce meses"],["Correcto: a ello se añaden una distribución regional y signos de hipersensibilidad evocada.","Falso: la duración exigida es más larga.","Falso: el punto de corte establecido es más corto.","Falso: esa duración supera con mucho el criterio."]],
  "74": ["¿Qué tipo de distribución exigen los criterios del dolor nociplástico?",["Una distribución regional, no neuroanatómica","Una distribución estrictamente dermatómica","Una distribución limitada a una sola articulación","Una distribución sistemáticamente bilateral"],["Correcto: una distribución dermatómica orientaría hacia un dolor neuropático.","Falso: esa distribución sugiere una afectación neuropática.","Falso: la localización estricta sugiere un dolor nociceptivo.","Falso: la bilateralidad no se exige."]],
  "75": ["¿Qué signo clínico es obligatorio para aceptar un dolor nociplástico?",["Una hipersensibilidad evocada en la zona dolorosa","Una alodinia extendida a todo el cuerpo","Un déficit sensitivo objetivo al monofilamento","Un dolor reproducido por las pruebas neurodinámicas"],["Correcto: alodinia mecánica estática o dinámica, al calor o al frío.","Falso: basta con que esté presente en la región dolorosa.","Falso: ese déficit sugiere una neuropatía.","Falso: ese signo orienta hacia un dolor neuropático."]],
  "76": ["¿Qué criterio facultativo hace que un dolor nociplástico sea solo probable?",["Al menos una comorbilidad, como un trastorno del sueño","Una duración superior a tres meses","Una distribución regional del dolor","Una hipersensibilidad evocada en la zona dolorosa"],["Correcto: también cuentan la hipersensibilidad al ruido o a la luz, la fatiga y los trastornos cognitivos.","Falso: esa duración es un criterio obligatorio.","Falso: ese criterio también es obligatorio.","Falso: ese signo forma parte de los criterios obligatorios."]],
  "77": ["¿Qué agrupación clínica sugiere un dolor neuropático?",["Dolor localizado, mecánico y proporcionado","Distribución dermatómica con disestesias claras","Dolor desproporcionado y zonas difusas","Fuerte asociación con factores psicosociales"],["Correcto: un antecedente de lesión nerviosa completa el cuadro.","Falso: esa agrupación sugiere un dolor nociceptivo.","Falso: esa agrupación sugiere un dolor nociplástico.","Falso: esa asociación orienta hacia el perfil nociplástico."]],
  "78": ["¿Qué agrupación clínica sugiere un dolor nociceptivo?",["Distribución dermatómica y pruebas neurodinámicas positivas","Distribución dermatómica con disestesias","Zonas difusas y no anatómicas","Hipersensibilidad al ruido y a la luz"],["Correcto: a ello se añade la ausencia de disestesias, de dolor nocturno y de posturas antálgicas.","Falso: esa agrupación sugiere un dolor neuropático.","Falso: esa agrupación sugiere un dolor nociplástico.","Falso: esas comorbilidades orientan hacia el perfil nociplástico."]],
  "79": ["¿Qué dato va EN CONTRA de un dolor puramente nociceptivo?",["La presencia de disestesias","Un dolor localizado y bien delimitado","Una relación mecánica clara con los movimientos","Una intensidad proporcionada a la solicitación"],["Correcto: su ausencia forma parte de la agrupación nociceptiva, junto con la del dolor nocturno.","Falso: esa localización pertenece a la agrupación nociceptiva.","Falso: esa relación es característica de la agrupación nociceptiva.","Falso: esa proporción pertenece a la agrupación nociceptiva."]],
  "80": ["¿Qué característica distingue una fibra A beta de una fibra A delta?",["La fibra A beta es mecánica y la A delta, nociceptiva","La fibra A beta es nociceptiva y la A delta, mecánica","La fibra A beta no está mielinizada","La fibra A delta es la más rápida de las dos"],["Correcto: la fibra A beta es además más gruesa y más rápida.","Falso: los dos papeles están invertidos.","Falso: solo las fibras C son amielínicas.","Falso: la fibra A beta, más gruesa, conduce más rápido."]],
  "81": ["¿Está establecida la relación causal entre dolor crónico y sensibilización central?",["No, no está demostrada","Sí, la sensibilización causa siempre la cronicidad","Sí, la cronicidad causa siempre la sensibilización","Sí, ambos conceptos son equivalentes"],["Correcto: uno se define por una duración y el otro es un mecanismo; confundirlos es un error frecuente.","Falso: esa relación causal no está demostrada.","Falso: esa causalidad tampoco está establecida.","Falso: son dos conceptos de naturaleza distinta."]],
  "82": ["¿Qué punto de corte se aplica al índice de dolor generalizado?",["Siete","Cuatro","Doce","Cuarenta"],["Correcto: el DN4 aplica cuatro y el inventario de sensibilización central, cuarenta.","Falso: ese punto de corte corresponde al cuestionario DN4.","Falso: ese punto de corte corresponde al cuestionario de dolor neuropático.","Falso: ese punto de corte corresponde al inventario de sensibilización central."]],
  "83": ["¿Qué es la hiperestesia?",["Una sensación aumentada, no siempre dolorosa","Un dolor aumentado frente a un estímulo nociceptivo","Un dolor frente a un estímulo no nociceptivo","Una respuesta exagerada y retardada"],["Correcto: se diferencia de la hiperalgesia, que se refiere a un estímulo nociceptivo.","Falso: esa definición corresponde a la hiperalgesia.","Falso: esa definición corresponde a la alodinia.","Falso: esa definición corresponde a la hiperpatía."]],
  "84": ["¿Cuáles son las cinco dimensiones de las creencias del paciente según el modelo del sentido común?",["Identidad, causa, consecuencia, cronología y control","Intensidad, duración, localización, cualidad y repercusión","Rumiación, magnificación, indefensión, miedo y evitación","Seguridad, confianza, colaboración, autonomía y elección"],["Correcto: estas dimensiones estructuran la representación que el paciente se hace de su dolor.","Falso: esos elementos describen el dolor, no las creencias.","Falso: esos conceptos pertenecen al catastrofismo y al modelo de miedo-evitación.","Falso: esos principios pertenecen a la atención informada sobre el trauma."]],
  "85": ["¿Cómo expresa un paciente la dimensión «consecuencia» de sus creencias?",["Hay que proteger y descansar para curarse","El dolor es señal de una lesión","Esto empeora inevitablemente con la edad","Hay que reparar o sustituir lo que está desgastado"],["Correcto: la dimensión identidad se expresa, en cambio, con la idea de que el dolor señala una lesión.","Falso: esa creencia pertenece a la dimensión identidad.","Falso: esa creencia pertenece a la dimensión cronología.","Falso: esa creencia pertenece al control, con un afrontamiento pasivo."]],
  "86": ["¿Qué es el dolor mixto?",["La superposición de varios mecanismos de dolor","Un dolor a la vez agudo y crónico","Un dolor a la vez local e irradiado","Un dolor percibido en dos regiones distintas"],["Correcto: el nociceptivo, el neuropático y el nociplástico pueden coexistir.","Falso: la cronología no sustenta esta clasificación.","Falso: la topografía no es el criterio.","Falso: la localización no define este término."]],
  "87": ["¿Qué reflejan los llamados signos negativos en una afectación nerviosa?",["Una pérdida objetiva de fuerza o de sensibilidad","Descargas ectópicas espontáneas y repetidas","Hormigueos y quemazón","Una alodinia mecánica dinámica"],["Correcto: caracterizan la neuropatía, mientras que los signos positivos reflejan el dolor neuropático.","Falso: esas descargas producen signos positivos.","Falso: son signos positivos.","Falso: también se trata de un signo positivo."]],
  "88": ["¿Qué es la hipoalgesia?",["Un dolor disminuido frente a un estímulo nociceptivo","Un dolor aumentado frente a un estímulo nociceptivo","Una sensación disminuida, no dolorosa","Una ausencia total de sensación"],["Correcto: la hiperalgesia designa, al contrario, un dolor aumentado ante el mismo tipo de estímulo.","Falso: esa definición corresponde a la hiperalgesia.","Falso: esa definición corresponde a la hipoestesia.","Falso: la abolición completa es la anestesia."]],
  "89": ["¿Qué hay que hacer con todo relato de dolor de un paciente?",["Aceptarlo","Contrastarlo con las pruebas de imagen","Ponderarlo según el perfil psicológico","Validarlo mediante un marcador biológico"],["Correcto: dado que el dolor es siempre subjetivo, este principio figura entre las notas de la definición.","Falso: la ausencia de lesión visible no invalida la queja.","Falso: esa ponderación contradice el principio establecido.","Falso: no existe ningún marcador objetivo del dolor."]],
  "90": ["¿Qué sostiene la red por defecto en el modelo de la triple red?",["El concepto de uno mismo","La memoria de trabajo","La priorización de la información","El procesamiento sensorial primario"],["Correcto: la red ejecutiva central sostiene la memoria de trabajo.","Falso: esa función corresponde a la red ejecutiva central.","Falso: esa función corresponde a la red de la saliencia.","Falso: ese procesamiento no corresponde a ninguna de estas tres redes."]],
  "91": ["¿Qué sostiene la red ejecutiva central en el modelo de la triple red?",["La memoria de trabajo","El concepto de uno mismo","La priorización de los estímulos salientes","La modulación descendente del dolor"],["Correcto: la red de la saliencia prioriza y la red por defecto sostiene el concepto de uno mismo.","Falso: esa función corresponde a la red por defecto.","Falso: esa función corresponde a la red de la saliencia.","Falso: esa modulación corresponde al tronco del encéfalo."]],
  "92": ["¿Qué lugar ocupa el dolor crónico entre las causas de discapacidad?",["Es la primera causa","Es la tercera causa","No figura entre las primeras causas","Es la causa más infrecuente"],["Correcto: es la enfermedad crónica más extendida y el primer motivo de consulta.","Falso: su posición es aún más alta.","Falso: su peso es, al contrario, considerable.","Falso: esa afirmación es lo contrario de la realidad."]],
  "93": ["¿Qué proporción de la población padece dolor crónico?",["Más del treinta por ciento","Menos del cinco por ciento","Alrededor del diez por ciento","Más del ochenta por ciento"],["Correcto: esta prevalencia la convierte en la enfermedad crónica más extendida.","Falso: esa estimación queda muy por debajo de la realidad.","Falso: la prevalencia real es bastante mayor.","Falso: esa proporción está sobrestimada."]],
  "94": ["¿Qué abarca la dimensión «identidad» del modelo del sentido común?",["El dolor es señal de una lesión","Hay que descansar para curarse","Esto empeora con la edad","Hay que sustituir lo desgastado por algo nuevo"],["Correcto: la dimensión consecuencia se refiere, en cambio, a la necesidad de proteger y descansar.","Falso: esa creencia pertenece a la dimensión consecuencia.","Falso: esa creencia pertenece a la cronología.","Falso: esa creencia pertenece al control."]],
  "95": ["¿Qué tipo de afrontamiento refleja la idea de reparar o sustituir lo que está desgastado?",["Un afrontamiento pasivo","Un afrontamiento activo","Un afrontamiento mixto","Un afrontamiento diferido"],["Correcto: se opone al afrontamiento activo, hecho de ejercicio, autocuidado y reestructuración.","Falso: el afrontamiento activo se basa en la implicación del paciente.","Falso: no es esa la categoría que se maneja aquí.","Falso: esa categoría no existe en este modelo."]],
  "96": ["¿Cuál es la secuencia del modelo de miedo-evitación?",["Catastrofismo, miedo, hipervigilancia, evitación, discapacidad","Evitación, catastrofismo, miedo, discapacidad, confrontación","Miedo, confrontación, recuperación, discapacidad, depresión","Hipervigilancia, recuperación, miedo, evitación, curación"],["Correcto: esta cadena mantiene el dolor, mientras que la confrontación conduce a la recuperación.","Falso: el orden de las etapas es erróneo.","Falso: la confrontación pertenece a la vía favorable.","Falso: esa secuencia mezcla las dos vías."]],
  "97": ["¿Qué vía conduce a la recuperación en el modelo de miedo-evitación?",["Ausencia de temor y, después, confrontación","Temor moderado y, después, protección prudente","Hipervigilancia y, después, vigilancia atenta","Reposo prolongado y, después, reanudación muy lenta"],["Correcto: se opone al bucle catastrofismo-evitación-discapacidad.","Falso: la protección mantiene la evitación.","Falso: la hipervigilancia pertenece a la vía desfavorable.","Falso: el reposo prolongado refuerza la evitación."]],
  "98": ["¿Cuáles son los tres componentes del catastrofismo?",["Rumiación, magnificación e indefensión","Miedo, evitación e hipervigilancia","Identidad, causa y consecuencia","Ansiedad, depresión y somatización asociadas"],["Correcto: estos tres componentes estructuran el cuestionario que lo evalúa.","Falso: esos conceptos pertenecen al modelo de miedo-evitación.","Falso: esas dimensiones pertenecen al modelo del sentido común.","Falso: esos conceptos no definen el catastrofismo."]],
  "99": ["¿Qué efecto tiene el catastrofismo sobre el sistema nervioso autónomo?",["Reduce la variabilidad y la actividad parasimpática","Aumenta la variabilidad cardíaca y la actividad parasimpática","No tiene ningún efecto sobre el sistema autónomo","Aumenta el tono vagal en reposo"],["Correcto: también reduce la inhibición prefrontal sobre la amígdala y el funcionamiento opioide.","Falso: se observa lo contrario.","Falso: su repercusión autonómica está bien documentada.","Falso: el tono parasimpático está, al contrario, disminuido."]],
  "100": ["¿Qué citocina está aumentada en caso de catastrofismo?",["La interleucina 6","La interleucina 10","El factor de crecimiento nervioso","El interferón gamma"],["Correcto: el catastrofismo también se correlaciona negativamente con el sistema inhibidor descendente.","Falso: no es la citocina que se cita aquí.","Falso: no se menciona en este contexto.","Falso: no figura entre los marcadores establecidos."]],
  "101": ["¿Qué parte del beneficio de los tratamientos activos podría representar la reducción del catastrofismo?",["Entre el treinta y cinco y el cuarenta por ciento","Menos del cinco por ciento","Alrededor del diez por ciento","Más del ochenta por ciento"],["Correcto: por eso constituye una diana terapéutica en sí misma.","Falso: esa estimación queda muy por debajo de la realidad.","Falso: la proporción real es bastante mayor.","Falso: esa proporción está sobrestimada."]],
  "102": ["¿Qué punto de corte se aplica a la escala de catastrofismo ante el dolor?",["Treinta","Diecisiete","Treinta y siete","Cincuenta y dos"],["Correcto: la escala va de cero a cincuenta y dos.","Falso: ese valor es el límite inferior de otra escala.","Falso: ese punto de corte corresponde a la escala de kinesiofobia.","Falso: ese valor es el máximo de la escala, no su punto de corte."]],
  "103": ["¿Qué punto de corte se aplica a la escala de kinesiofobia de once ítems?",["Treinta y siete","Treinta","Diecisiete","Sesenta y ocho"],["Correcto: la escala va de diecisiete a sesenta y ocho, con cuatro ítems invertidos.","Falso: ese punto de corte corresponde a la escala de catastrofismo.","Falso: ese valor es el mínimo de la escala.","Falso: ese valor es el máximo de la escala."]],
  "104": ["¿Cuántos ítems están invertidos en la escala de kinesiofobia de once ítems?",["Cuatro","Dos","Seis","Ninguno"],["Correcto: se trata de los ítems cuatro, ocho, doce y dieciséis.","Falso: el número de ítems invertidos es mayor.","Falso: esa cifra supera la realidad.","Falso: esta escala sí contiene ítems invertidos."]],
  "105": ["¿A partir de qué puntuación resulta clínicamente significativa la escala hospitalaria de ansiedad y depresión?",["Por encima de once","Por encima de siete","Por encima de quince","Por encima de veinte"],["Correcto: por debajo de siete el resultado es negativo, y de ocho a diez el trastorno es leve.","Falso: por debajo de siete el resultado es negativo, pero el punto de corte clínico es más alto.","Falso: ese punto de corte es demasiado alto para esta escala.","Falso: ese punto de corte supera con mucho la graduación establecida."]],
  "106": ["¿A qué categoría corresponde un inventario de depresión de veintidós?",["Moderada","Mínima","Leve","Grave"],["Correcto: el intervalo de diecisiete a veintinueve corresponde al grado moderado.","Falso: esa categoría va de cero a nueve.","Falso: esa categoría va de diez a dieciséis.","Falso: esa categoría empieza en treinta."]],
  "107": ["¿Cuál es el rango del cuestionario de salud del paciente de nueve ítems?",["De cero a veintisiete","De cero a cincuenta y dos","De diecisiete a sesenta y ocho","De cero a sesenta y tres"],["Correcto: de veinte a veintisiete el trastorno es grave.","Falso: ese rango corresponde a la escala de catastrofismo.","Falso: ese rango corresponde a la escala de kinesiofobia.","Falso: ese rango corresponde al inventario de depresión."]],
  "108": ["¿Qué modificación estructural se observa en la lumbalgia crónica?",["Una disminución de la sustancia gris prefrontal","Un aumento de la sustancia gris de la corteza motora","Una atrofia del cerebelo posterior","Una hipertrofia del hipocampo"],["Correcto: es bilateral y se acompaña de un descenso de las funciones ejecutivas.","Falso: no se describe ningún aumento de ese tipo.","Falso: no es esa la localización descrita.","Falso: no se refiere aquí ninguna hipertrofia."]],
  "109": ["¿Qué función ejecutiva depende de la corteza prefrontal dorsolateral?",["La memoria de trabajo","La toma de decisiones","El procesamiento sensorial primario","La regulación autonómica cardíaca"],["Correcto: el control atencional también se le atribuye, junto con la prefrontal ventrolateral.","Falso: se atribuye más bien a la prefrontal medial.","Falso: esa función no corresponde a la corteza prefrontal.","Falso: esa regulación corresponde a otras estructuras."]],
  "110": ["¿Qué relación une la activación de la prefrontal ventrolateral y la intensidad del dolor?",["Está relacionada negativamente con ella","Está relacionada positivamente con ella","Es totalmente independiente de ella","Varía de forma impredecible"],["Correcto: su activación, en cambio, se relaciona positivamente con el control del dolor.","Falso: esa relación está invertida.","Falso: la correlación está establecida.","Falso: la relación es, al contrario, sistemática."]],
  "111": ["¿Cómo se define la hipervigilancia en el dolor crónico?",["Un esquema dominante que se autorrefuerza","Una simple vigilancia excesiva y voluntaria","Una distracción permanente frente al dolor","Una ausencia de reacción a los estímulos amenazantes"],["Correcto: no es una simple vigilancia excesiva, sino un esquema cognitivo-emocional.","Falso: esa reducción es precisamente el error que hay que evitar.","Falso: es lo contrario: la atención permanece captada.","Falso: esa descripción es lo opuesto a la hipervigilancia."]],
  "112": ["¿Qué es una vigilancia de tipo bottom-up?",["Una vigilancia automática, ligada al estímulo","Una vigilancia intencional y controlada","Una vigilancia aprendida a lo largo de las consultas","Una vigilancia limitada al sueño REM"],["Correcto: la vigilancia top-down es, al contrario, intencional.","Falso: esa descripción corresponde a la vigilancia top-down.","Falso: el aprendizaje no es el criterio aplicado.","Falso: ese concepto no guarda relación con esta distinción."]],
  "113": ["¿Cómo se define el sufrimiento en relación con el dolor?",["Una amenaza percibida para la integridad y la identidad","Un dolor de intensidad especialmente elevada","Un dolor que persiste más de seis meses","Un dolor sin lesión tisular visible"],["Correcto: la vergüenza, la culpa, la decepción con uno mismo y el agotamiento son sus signos.","Falso: la intensidad no define el sufrimiento.","Falso: esa definición corresponde a la cronicidad.","Falso: la ausencia de lesión no define el sufrimiento."]],
  "114": ["¿Qué estructuras comparte el dolor social con el dolor físico?",["La corteza cingulada anterior y la ínsula","Únicamente la corteza somatosensorial primaria","El cerebelo y el tronco del encéfalo","Únicamente el hipocampo y la amígdala"],["Correcto: este solapamiento explica el malestar ligado a la distancia con los seres queridos.","Falso: no es esa el área del solapamiento descrito.","Falso: no son esas las estructuras citadas.","Falso: esas estructuras no constituyen el solapamiento descrito."]],
  "115": ["¿Cuánto tarda un paciente en responder a una pregunta abierta?",["Dos minutos o menos","Unos diez minutos","Unos veinte minutos","Menos de diez segundos"],["Correcto: y, sin embargo, se le interrumpe de media al cabo de veintitrés segundos.","Falso: ese tiempo supera con mucho lo observado.","Falso: esa duración está muy sobrestimada.","Falso: ese tiempo es demasiado corto."]],
  "116": ["¿Al cabo de cuánto tiempo se interrumpe de media a un paciente?",["Dos minutos o menos","Dos minutos exactamente","Cinco minutos","Menos de diez segundos"],["Correcto: cuando le harían falta menos de dos minutos para terminar.","Falso: esa duración corresponde al tiempo que necesitaría.","Falso: ese tiempo supera con mucho lo observado.","Falso: la interrupción se produce aún antes."]],
  "117": ["¿Qué es lo que más valoran los pacientes en la consulta?",["La escucha, el tiempo, el apoyo y la explicación","La prescripción y las pruebas complementarias","La rapidez y la eficiencia de la cita","Acudir de inmediato a una opinión especializada"],["Correcto: los profesionales, por su parte, sobrevaloran la importancia de la prescripción.","Falso: es lo que priorizan los profesionales, no los pacientes.","Falso: no es eso lo que se desprende de los trabajos citados.","Falso: no es esa la expectativa descrita."]],
  "118": ["¿Por cuánto multiplican las experiencias adversas en la infancia el riesgo de dolor crónico generalizado?",["Por dos o tres","Por diez o veinte","No modifican ese riesgo","Lo reducen a la mitad"],["Correcto: se relacionan con la fibromialgia, la fatiga crónica y el colon irritable.","Falso: esa multiplicación está muy sobrestimada.","Falso: la asociación está bien establecida.","Falso: aumentan el riesgo, no lo reducen."]],
  "119": ["¿Qué trastorno constituye un factor de riesgo de paso del dolor agudo al crónico?",["El estrés postraumático","El trastorno obsesivo","El trastorno bipolar de tipo dos","La fobia social aislada"],["Correcto: se suma a las experiencias adversas en la infancia.","Falso: no se cita en este contexto.","Falso: no se menciona como factor de riesgo.","Falso: no se contempla aquí."]],
  "120": ["¿Cuáles son los principios de la atención informada sobre el trauma?",["Seguridad, confianza, colaboración, elección y consideración","Identidad, causa, consecuencia, cronología y control","Rumiación, magnificación, indefensión y evitación","Escucha, prescripción, prueba y derivación"],["Correcto: la pregunta que guía la atención pasa a ser «¿qué necesita este paciente?».","Falso: esas dimensiones pertenecen al modelo del sentido común.","Falso: esos conceptos pertenecen al catastrofismo.","Falso: esa serie no corresponde a ninguno de los marcos descritos."]],
  "121": ["¿Cuál es la pregunta que guía la atención informada sobre el trauma?",["¿Qué necesita este paciente?","¿Qué le pasa a este paciente?","¿Qué trauma hay que tratar en primer lugar?","¿Qué lesión explica el dolor que refiere?"],["Correcto: sustituye a la pregunta «¿qué le pasa?».","Falso: es precisamente la pregunta que se trata de superar.","Falso: el objetivo no es tratar el trauma.","Falso: esa pregunta pertenece al modelo biomédico."]],
  "122": ["¿Cuál es el objetivo de la atención informada sobre el trauma?",["Adaptar la atención, sin tratar el trauma","Tratar el trauma inicial del paciente","Explorar sistemáticamente la infancia del paciente","Derivar a todo paciente a un psicoterapeuta"],["Correcto: tratar el trauma queda explícitamente fuera de su objeto.","Falso: ese objetivo queda explícitamente descartado.","Falso: esa exploración sistemática no es el objetivo.","Falso: la derivación sistemática no es el principio."]],
  "123": ["¿Qué designan las banderas rosas?",["Factores psicosociales protectores","Factores psicosociales de riesgo","Signos de alarma de patología grave","Factores ligados al entorno laboral"],["Correcto: se oponen a las banderas amarillas, que señalan un riesgo.","Falso: esos factores son las banderas amarillas.","Falso: esos signos son las banderas rojas.","Falso: esos factores pertenecen a otra categoría de banderas."]],
  "124": ["¿Qué factor forma parte de las banderas rosas?",["Un locus de control interno","Un locus de control externo","Un afrontamiento pasivo del dolor","Un catastrofismo moderado pero persistente"],["Correcto: la alianza de confianza, las expectativas positivas, la autoeficacia y el afrontamiento activo también forman parte de ellas.","Falso: aumenta la dependencia de los tratamientos pasivos.","Falso: el afrontamiento pasivo es desfavorable.","Falso: el catastrofismo es un factor de riesgo."]],
  "125": ["¿Cuánto vale la alianza terapéutica como factor pronóstico?",["Un factor independiente, comparable a la técnica","Un factor secundario, muy inferior a la técnica","Un factor sin influencia demostrada en los resultados","Un factor que solo cuenta en el dolor agudo"],["Correcto: actúa reduciendo la incertidumbre y activando expectativas positivas.","Falso: su influencia es comparable a la de la técnica aplicada.","Falso: su papel predictivo está establecido.","Falso: su papel está documentado sobre todo en el dolor persistente."]],
  "126": ["¿Qué reúne la alianza terapéutica?",["La confianza, la comunicación y unos objetivos compartidos","La técnica, la experiencia y la reputación","La duración, la frecuencia y el coste de las sesiones","El diagnóstico, el pronóstico y la prescripción"],["Correcto: estos tres elementos constituyen su base.","Falso: esos elementos no definen la alianza.","Falso: esos parámetros organizativos no la definen.","Falso: esos elementos pertenecen al proceso médico."]],
  "127": ["¿De dónde proviene el efecto placebo?",["Del contexto: rituales, palabras y gestos","De la sustancia inerte administrada al paciente","De una sugestión hipnótica voluntaria","De una mejoría espontánea de la enfermedad"],["Correcto: no proviene de una sustancia inerte, al contrario de lo que suele creerse.","Falso: es el contexto, y no la sustancia, lo que produce el efecto.","Falso: la hipnosis no es el mecanismo descrito.","Falso: la evolución natural es otro concepto."]],
  "128": ["¿Por qué mediadores pasa el efecto placebo?",["Opioides endógenos, dopamina y endocannabinoides","Colecistocinina y hormonas del estrés circulantes","La histamina y las prostaglandinas locales","El glutamato y la sustancia P espinal"],["Correcto: la corteza prefrontal y la ínsula también participan.","Falso: esos mediadores sostienen el efecto nocebo.","Falso: esos mediadores son los de la inflamación.","Falso: esos mediadores son excitadores y nociceptivos."]],
  "129": ["¿Qué mediador sostiene el efecto nocebo?",["La colecistocinina","La dopamina mesolímbica","Los endocannabinoides","Las endorfinas circulantes"],["Correcto: a ello se añaden la desactivación de los opioides endógenos y la actividad de las regiones de la amenaza.","Falso: participa en el efecto placebo.","Falso: también participan en el efecto placebo.","Falso: pertenecen al efecto placebo."]],
  "130": ["¿Cuál es el efecto del nocebo sobre un tratamiento real?",["Reduce su eficacia y genera hiperalgesia","Refuerza su eficacia por contraste","Simplemente lo vuelve ineficaz, sin dolor","No modifica en nada su eficacia"],["Correcto: las expectativas desfavorables bastan para modificar la respuesta al tratamiento.","Falso: el efecto es, al contrario, perjudicial.","Falso: puede añadirse una hiperalgesia.","Falso: su influencia está bien demostrada."]],
  "131": ["¿Cómo se define la autoeficacia?",["La creencia en la propia capacidad de manejar el dolor","La capacidad física realmente medida","La confianza depositada en el terapeuta","La adherencia al programa de ejercicios propuesto"],["Correcto: se distingue de la capacidad física real: es una percepción de control.","Falso: esa es precisamente la distinción que hay que hacer.","Falso: esa confianza pertenece a la alianza terapéutica.","Falso: la adherencia es una consecuencia, no la definición."]],
  "132": ["¿Cómo se puede mejorar la autoeficacia de un paciente con dolor?",["Mediante la educación y el ejercicio terapéutico","Mediante el reposo prolongado y la protección del segmento","Mediante la prescripción de analgésicos potentes","Mediante el abandono de toda actividad física de riesgo"],["Correcto: predice una reducción de la discapacidad.","Falso: esas medidas refuerzan, al contrario, la evitación.","Falso: el tratamiento pasivo no mejora la percepción de control.","Falso: esa conducta favorece la kinesiofobia."]],
  "133": ["¿Qué refleja un locus de control interno?",["Puedo influir en mi recuperación","Mi recuperación depende de los tratamientos recibidos","Mi dolor es señal de una lesión grave","Mi estado empeorará inevitablemente con la edad"],["Correcto: aumenta la adherencia y reduce el dolor y la discapacidad.","Falso: esa creencia refleja un locus externo.","Falso: esa creencia pertenece al catastrofismo.","Falso: esa creencia pertenece a la dimensión cronología."]],
  "134": ["¿Qué consecuencia tiene un locus de control externo?",["Una dependencia pasiva y un riesgo de cronificación","Una mejor adherencia a los ejercicios activos","Una clara reducción del dolor y de la discapacidad","Una mayor autonomía en el manejo"],["Correcto: el locus interno favorece, en cambio, el afrontamiento activo.","Falso: esa adherencia acompaña al locus interno.","Falso: ese beneficio se asocia al locus interno.","Falso: la autonomía caracteriza al locus interno."]],
  "135": ["¿Qué estrategia pertenece al afrontamiento activo cognitivo?",["La reestructuración y la aceptación","El ejercicio y el autocuidado diario","La dependencia de los analgésicos","La evitación y la resignación progresiva"],["Correcto: el ejercicio y el autocuidado constituyen la vertiente conductual.","Falso: esa vertiente es conductual, no cognitiva.","Falso: esa conducta pertenece al afrontamiento pasivo.","Falso: esas conductas también pertenecen a la vertiente pasiva."]],
  "136": ["¿Qué cambio de objetivo propone la terapia de aceptación y compromiso?",["Pasar de eliminar el dolor a vivir plenamente","Pasar de vivir con el dolor a eliminarlo","Pasar de la actividad al reposo protector","Pasar del tratamiento activo al tratamiento pasivo"],["Correcto: su efecto es moderado sobre la interferencia y pequeño sobre la intensidad del dolor.","Falso: el objetivo es exactamente el inverso.","Falso: esa conducta iría contra el espíritu del enfoque.","Falso: el enfoque valora la implicación del paciente."]],
  "137": ["¿Cuál es el tamaño del efecto de la terapia de aceptación y compromiso sobre la intensidad del dolor?",["Pequeño","Moderado","Grande","Nulo"],["Correcto: su efecto es moderado sobre la interferencia, la depresión y la aceptación.","Falso: ese tamaño corresponde a la interferencia y a la aceptación.","Falso: no se refiere ningún efecto grande sobre la intensidad.","Falso: se observa un efecto pequeño pero real."]],
  "138": ["¿Sobre qué tiene la terapia de aceptación y compromiso un efecto moderado?",["Sobre la interferencia, la depresión y la aceptación","Sobre la intensidad del dolor que se siente a diario","Sobre la fuerza muscular y la resistencia","Sobre la movilidad articular medida"],["Correcto: su efecto sigue siendo pequeño sobre la intensidad del dolor en sí.","Falso: su efecto ahí es pequeño.","Falso: esos parámetros no son sus dianas.","Falso: no es ese el parámetro al que se dirige."]],
  "139": ["¿Cómo actúa la alianza terapéutica sobre el resultado del tratamiento?",["Reduciendo la incertidumbre y generando expectativas","Aumentando la dosis de tratamiento administrada","Reforzando la dependencia del terapeuta","Acortando la duración total de la atención"],["Correcto: su efecto pronóstico se ejerce por estas dos vías.","Falso: su efecto no pasa por la cantidad de atención.","Falso: ese efecto iría en contra del objetivo buscado.","Falso: no es ese el mecanismo descrito."]],
  "140": ["¿Cuál de estos no forma parte de los tratamientos no opioides?",["Oxicodona","Paracetamol","Ibuprofeno","Celecoxib"],["Correcto: la oxicodona es un opioide potente, administrado a razón de 5 mg cada seis u ocho horas.","Falso: el paracetamol es un analgésico no opioide.","Falso: es un antiinflamatorio no esteroideo y, por tanto, un no opioide.","Falso: es un inhibidor selectivo de la ciclooxigenasa 2, no opioide."]],
  "141": ["Sobre el tratamiento del dolor, señala la respuesta correcta:",["La aspirina, el paracetamol y los antiinflamatorios son analgésicos no opioides","La codeína y el tramadol son opioides potentes","La morfina y el fentanilo son opioides débiles","Los opioides no tienen efectos secundarios"],["Correcto: constituyen el primer escalón de la escalera analgésica.","Falso: son opioides débiles, cuyo lugar se cuestiona hoy en día.","Falso: son, al contrario, opioides potentes.","Falso: sus efectos adversos son numerosos y a veces graves."]],
  "142": ["Respecto a los inhibidores de la ciclooxigenasa, ¿cuál no posee efecto antiinflamatorio?",["El paracetamol","El celecoxib","La aspirina","El ibuprofeno"],["Correcto: es analgésico y antipirético, pero no es un antiinflamatorio.","Falso: es un inhibidor selectivo de la ciclooxigenasa 2 y es antiinflamatorio.","Falso: a dosis suficiente posee efecto antiinflamatorio.","Falso: es un antiinflamatorio no esteroideo de referencia."]],
  "143": ["¿Cuál de estos inhibidores de la ciclooxigenasa expone más al riesgo hemorrágico?",["Aspirina e ibuprofeno","Paracetamol solo","Celecoxib y etoricoxib","Ninguno de estos fármacos"],["Correcto: aumentan el riesgo de sangrado, al contrario que el paracetamol.","Falso: el paracetamol no expone a ese riesgo.","Falso: los coxibs exponen más bien al riesgo trombótico.","Falso: los antiinflamatorios no selectivos sí aumentan ese riesgo."]],
  "144": ["De estas opciones, ¿cuál no forma parte de las toxicidades de los antiinflamatorios no esteroideos?",["La toxicidad hepática","La toxicidad gástrica","El aumento del riesgo de sangrado","La toxicidad renal"],["Es la única que no figura: los efectos reconocidos son gástricos, renales, tensionales y cardiovasculares.","Falso: la afectación gástrica es el efecto adverso más clásico.","Falso: ese riesgo forma parte de los efectos reconocidos.","Falso: la nefrotoxicidad es un efecto bien establecido."]],
  "145": ["Sobre los coadyuvantes:",["Se utilizan por su componente neuropático","Ejercen sus efectos por vías directas","Su efecto máximo se alcanza en unas horas","La codeína pertenece al grupo de los coadyuvantes"],["Correcto: la gabapentina, la pregabalina, la duloxetina y la amitriptilina son sus representantes.","Falso: su acción es indirecta, sobre la modulación del dolor.","Falso: su efecto se instaura, al contrario, de forma progresiva.","Falso: la codeína es un opioide débil."]],
  "146": ["¿Cuál no es un coadyuvante?",["Antagonista gabaérgico","Antidepresivo y ansiolítico","Neuroléptico","Corticoide"],["Correcto: los gabapentinoides son análogos del GABA y no antagonistas.","Falso: la duloxetina y la amitriptilina son coadyuvantes de referencia.","Falso: los neurolépticos figuran entre los coadyuvantes clásicos.","Falso: los corticoides forman parte de los coadyuvantes."]],
  "147": ["¿Para qué dolor se concibió la escalera analgésica de la Organización Mundial de la Salud?",["El dolor oncológico","El dolor crónico primario","El dolor posoperatorio agudo","El dolor neuropático periférico"],["Correcto: no se aplica tal cual al dolor crónico primario no oncológico.","Falso: precisamente no se le aplica tal cual.","Falso: no es el marco para el que se propuso.","Falso: no se concibió para este tipo de dolor."]],
  "148": ["¿Cuántos escalones tiene la escalera analgésica clásica?",["Tres","Dos","Cuatro","Cinco"],["Correcto: se propone un cuarto escalón intervencionista, sin ser una recomendación oficial.","Falso: el modelo clásico tiene uno más.","Falso: el cuarto escalón es solo una extensión práctica propuesta.","Falso: no se describe ningún modelo de cinco escalones."]],
  "149": ["¿Qué actualización de la escalera analgésica se ha aceptado para el dolor moderado a intenso?",["Pasar directamente a los opioides potentes","Empezar sistemáticamente por los opioides débiles","Suprimir el recurso a los coadyuvantes","Reservar los antiinflamatorios para el último escalón"],["Correcto: el valor del escalón de los opioides débiles se cuestiona hoy en día.","Falso: es precisamente lo que se cuestiona.","Falso: los coadyuvantes siguen siendo la base del abordaje.","Falso: pertenecen al primer escalón."]],
  "150": ["¿Qué reúne el cuarto escalón propuesto de la escalera analgésica?",["Bloqueos, radiofrecuencia y neuromodulación","Los opioides potentes a dosis altas","Los antiinflamatorios asociados a los coadyuvantes","La psicoterapia y la educación terapéutica"],["Correcto: no es una recomendación oficial, sino una extensión práctica.","Falso: pertenecen al tercer escalón.","Falso: esa asociación pertenece al primer escalón.","Falso: no constituyen este escalón intervencionista."]],
  "151": ["¿Qué se recomienda en primer lugar en el dolor crónico primario no oncológico?",["El ejercicio, la educación y la psicoterapia","Los opioides potentes desde el principio","Los antiinflamatorios a largo plazo","Las infiltraciones repetidas de corticoides locales"],["Correcto: no se aconseja empezar por analgésicos convencionales, opioides incluidos.","Falso: su uso se desaconseja expresamente en este contexto.","Falso: los analgésicos convencionales no son la primera opción.","Falso: ese enfoque no es la prioridad recomendada."]],
  "152": ["¿Qué es el ascensor analgésico?",["Se entra directamente en el nivel de intensidad que corresponde","Se suben los escalones uno a uno, sin saltarse ninguno","Se empieza siempre por el escalón más alto","Se reservan los coadyuvantes para el último nivel alcanzado"],["Correcto: se sube o se baja según la reevaluación, con los coadyuvantes en la base.","Falso: es el modelo clásico que precisamente viene a corregir.","Falso: la entrada se hace en el nivel que corresponde a la situación.","Falso: los coadyuvantes están en la base, sea cual sea el nivel."]],
  "153": ["¿Cuál es la dosis máxima diaria de paracetamol en el adulto sano?",["Cuatro gramos","Dos gramos","Tres gramos","Seis gramos"],["Correcto: baja a tres gramos a partir de los sesenta y cinco años o en caso de hepatopatía leve.","Falso: esa dosis es inferior al máximo autorizado.","Falso: ese límite se aplica al paciente mayor o con hepatopatía.","Falso: esa dosis supera con mucho el umbral de toxicidad."]],
  "154": ["¿Cuál es la dosis máxima de paracetamol a partir de los sesenta y cinco años?",["Tres gramos al día","Cuatro gramos al día","Dos gramos al día","Un gramo al día"],["Correcto: el mismo límite se aplica en caso de hepatopatía leve.","Falso: esa dosis corresponde al adulto sano más joven.","Falso: el límite establecido es algo más alto.","Falso: esa restricción es excesiva."]],
  "155": ["¿Cuál es la contraindicación absoluta del paracetamol?",["La insuficiencia hepática grave","La insuficiencia renal terminal","La úlcera gastroduodenal activa","La insuficiencia cardíaca grave"],["Correcto: el alcoholismo activo es otra de ellas.","Falso: esa situación afecta sobre todo a los antiinflamatorios.","Falso: esa contraindicación afecta a los antiinflamatorios.","Falso: contraindica los antiinflamatorios, no el paracetamol."]],
  "156": ["¿Cuál es la dosis máxima diaria de ibuprofeno?",["Dos mil cuatrocientos miligramos","Mil miligramos","Ciento cincuenta miligramos como máximo","Seis mil miligramos"],["Correcto: la posología habitual es de 400 a 600 miligramos cada ocho horas.","Falso: ese límite corresponde al naproxeno.","Falso: ese límite corresponde al diclofenaco.","Falso: esa dosis supera con mucho el máximo."]],
  "157": ["¿Cuál es la dosis máxima diaria de diclofenaco?",["Ciento cincuenta miligramos","Dos mil cuatrocientos miligramos","Mil miligramos","Cincuenta miligramos"],["Correcto: la posología habitual es de cincuenta miligramos cada ocho a doce horas.","Falso: ese límite corresponde al ibuprofeno.","Falso: ese límite corresponde al naproxeno.","Falso: ese valor es la dosis por toma, no el máximo diario."]],
  "158": ["¿Qué contraindicación obstétrica tienen los antiinflamatorios no esteroideos?",["El tercer trimestre de embarazo","El primer trimestre de embarazo","La lactancia materna exclusiva","El periodo preconcepcional"],["Correcto: la úlcera activa, la insuficiencia renal avanzada y la insuficiencia cardíaca grave son las otras contraindicaciones.","Falso: el que se contempla es el tercer trimestre.","Falso: esa situación no constituye la contraindicación establecida.","Falso: no es ese el periodo contemplado."]],
  "159": ["¿En qué situación se prefiere un coxib?",["En caso de riesgo digestivo alto","En caso de cardiopatía isquémica conocida","En caso de antecedente de ictus","En caso de insuficiencia cardíaca avanzada"],["Correcto: producen menos gastropatía, pero más riesgo trombótico.","Falso: es, al contrario, una contraindicación.","Falso: también se trata de una contraindicación.","Falso: esa situación contraindica los coxibs."]],
  "160": ["¿Qué contraindicación comparten los coxibs?",["Cardiopatía isquémica e insuficiencia cardíaca","Úlcera gastroduodenal no complicada y activa","La migraña crónica con aura","El asma bien controlada con tratamiento"],["Correcto: la razón es su mayor riesgo trombótico.","Falso: precisamente están indicados en caso de riesgo digestivo.","Falso: no es una contraindicación establecida.","Falso: no es esa la situación descrita."]],
  "161": ["¿Cuál es la dosis máxima diaria de tramadol?",["Cuatrocientos miligramos","Quinientos miligramos","Doscientos miligramos","Mil miligramos"],["Correcto: la posología habitual es de cincuenta miligramos cada ocho horas.","Falso: ese límite corresponde al tapentadol.","Falso: ese límite es inferior al máximo autorizado.","Falso: esa dosis supera con mucho el máximo."]],
  "162": ["¿Qué contraindicación renal tiene el tramadol?",["Un aclaramiento inferior a treinta","Un aclaramiento inferior a noventa","Un aclaramiento superior a ciento veinte","Cualquier insuficiencia renal, incluso incipiente"],["Correcto: una epilepsia no controlada es la otra contraindicación.","Falso: ese umbral es mucho más permisivo.","Falso: un aclaramiento alto no contraindica nada.","Falso: el umbral establecido es preciso."]],
  "163": ["¿Qué contraindicación neurológica tiene el tramadol?",["La epilepsia no controlada","La migraña con aura visual","La neuropatía diabética periférica","La enfermedad de Parkinson incipiente"],["Correcto: reduce el umbral epileptógeno.","Falso: no constituye una contraindicación.","Falso: es, al contrario, una posible indicación.","Falso: no es una contraindicación establecida."]],
  "164": ["¿Cuánto tiempo se lleva puesto un parche de fentanilo transdérmico?",["Setenta y dos horas","Veinticuatro horas","Doce horas","Una semana"],["Correcto: la posología inicial va de doce a veinticinco microgramos por hora.","Falso: la duración de acción es más larga.","Falso: esa duración corresponde al parche de lidocaína.","Falso: esa duración supera la del dispositivo."]],
  "165": ["¿Qué contraindicación térmica tiene el fentanilo transdérmico?",["Una fiebre superior a treinta y nueve grados","Una hipotermia inferior a treinta y cinco grados","Una temperatura normal de treinta y siete grados","Cualquier variación térmica, aunque sea mínima"],["Correcto: el calor aumenta la absorción y expone a la sobredosificación.","Falso: lo que se contempla es la fiebre, no la hipotermia.","Falso: esa temperatura no plantea ningún problema.","Falso: el umbral establecido es preciso."]],
  "166": ["¿A quién está contraindicado el fentanilo transdérmico?",["Al paciente no tolerante a los opioides","Al paciente ya tratado con morfina oral","Al paciente de más de sesenta y cinco años","Al paciente con dolor neuropático"],["Correcto: una fiebre superior a treinta y nueve grados es la otra contraindicación.","Falso: la tolerancia previa es, al contrario, necesaria.","Falso: la edad no constituye una contraindicación absoluta.","Falso: ese tipo de dolor no es una contraindicación."]],
  "167": ["¿Cuál es la dosis de mantenimiento de la gabapentina en el dolor neuropático?",["De mil ochocientos a tres mil seiscientos miligramos","Trescientos miligramos al día","De ciento cincuenta a trescientos miligramos al día","Sesenta miligramos al día"],["Correcto: se empieza con trescientos miligramos por la noche y después se reparte en tres tomas.","Falso: esa dosis corresponde al inicio.","Falso: ese intervalo corresponde a la pregabalina.","Falso: esa dosis corresponde a la duloxetina."]],
  "168": ["¿Qué coadyuvante tiene una indicación adicional en la fibromialgia?",["La pregabalina","La gabapentina","La amitriptilina","La lidocaína tópica"],["Correcto: se prescribe de ciento cincuenta a trescientos miligramos cada doce horas.","Falso: no tiene esa indicación adicional.","Falso: no se cita para esta indicación.","Falso: su indicación es local y distinta."]],
  "169": ["¿Qué contraindicación oftalmológica tiene la amitriptilina?",["El glaucoma","La catarata incipiente","La degeneración macular","La retinopatía diabética"],["Correcto: la arritmia y la hiperplasia benigna de próstata son las otras.","Falso: no constituye una contraindicación.","Falso: no se cita como contraindicación.","Falso: no figura entre las contraindicaciones establecidas."]],
  "170": ["¿Cuál es la dosis máxima de lidocaína sin adrenalina?",["Cuatro coma cinco miligramos por kilogramo","Dos miligramos por kilogramo de peso","Diez miligramos por kilogramo","Un miligramo por kilogramo"],["Correcto: la bupivacaína, cardiotóxica, se limita a dos miligramos por kilogramo.","Falso: ese límite corresponde a la bupivacaína.","Falso: esa dosis supera con mucho el máximo.","Falso: ese límite es demasiado restrictivo."]],
  "171": ["¿Por qué tiene la bupivacaína una dosis máxima más baja?",["Por su cardiotoxicidad","Por su nefrotoxicidad","Por su hepatotoxicidad","Por su efecto alergizante"],["Correcto: se limita a dos miligramos por kilogramo.","Falso: no es esa la toxicidad implicada.","Falso: no es esa la toxicidad que limita su uso.","Falso: la alergia no es la razón que se invoca."]],
  "172": ["¿Qué ritmo de aplicación sigue un parche de lidocaína al cinco por ciento?",["Doce horas puesto y doce horas sin él","Veinticuatro horas de forma continua","Setenta y dos horas puesto","Seis horas puesto y después seis horas sin él"],["Correcto: este ritmo limita los efectos locales y el paso a la circulación.","Falso: no se recomienda llevarlo de forma continua.","Falso: esa duración corresponde al fentanilo transdérmico.","Falso: el ritmo establecido es de doce horas."]],
  "173": ["¿Qué riesgo conlleva la crema anestésica en el lactante?",["Una metahemoglobinemia","Una hepatotoxicidad aguda","Una insuficiencia renal aguda","Una depresión respiratoria"],["Correcto: se aplica a razón de un gramo por cada diez centímetros cuadrados, en oclusión durante una hora.","Falso: no es ese el riesgo descrito.","Falso: no es ese el riesgo que se teme.","Falso: corresponde más bien a los opioides."]],
  "174": ["¿Qué fármaco provoca mialgias y miopatías con elevación de las enzimas musculares?",["Las estatinas","Las fluoroquinolonas","Los inhibidores de la aromatasa","Los betabloqueantes"],["Correcto: por encima de cinco veces el límite superior hay que suspenderlas y derivar al paciente.","Falso: exponen sobre todo a tendinopatías.","Falso: producen más bien artralgias difusas.","Falso: limitan la frecuencia cardíaca sin afectación muscular."]],
  "175": ["¿Qué fármaco expone a una rotura del tendón de Aquiles?",["Las fluoroquinolonas","Las estatinas","Los inhibidores de la aromatasa","Los betabloqueantes"],["Correcto: hay que evitar el trabajo excéntrico y la carrera con impacto al menos cuatro semanas después.","Falso: exponen sobre todo a mialgias y miopatías.","Falso: producen artralgias difusas.","Falso: no exponen a ese riesgo tendinoso."]],
  "176": ["¿Cuánto tiempo se evita la carrera con impacto después de un tratamiento con fluoroquinolonas?",["Al menos cuatro semanas","Al menos una semana","Al menos seis meses","No hace falta ninguna precaución"],["Correcto: el trabajo excéntrico también debe evitarse durante ese periodo.","Falso: ese plazo es insuficiente.","Falso: ese plazo excede la recomendación.","Falso: el riesgo tendinoso persiste después de suspenderlas."]],
  "177": ["¿Cómo se dosifica el esfuerzo en un paciente que toma betabloqueantes?",["Por la percepción del esfuerzo o por el habla","Por una frecuencia cardíaca objetivo precisa","Por la medida de la presión arterial de esfuerzo","Únicamente por la duración total de la sesión"],["Correcto: los betabloqueantes limitan la frecuencia cardíaca, que deja de ser una referencia fiable.","Falso: la frecuencia está precisamente limitada por el tratamiento.","Falso: no es esa la referencia recomendada.","Falso: la duración por sí sola no informa sobre la intensidad."]],
  "178": ["¿Qué interacción expone a una insuficiencia renal aguda?",["Antiinflamatorio junto con un inhibidor de la enzima convertidora de la angiotensina","Opioide junto con una benzodiacepina sedante","Duloxetina junto con un triptán antimigrañoso","Metadona junto con un antidepresivo serotoninérgico"],["Correcto: esta asociación compromete la perfusión glomerular.","Falso: esa asociación expone a la depresión respiratoria.","Falso: esa asociación expone al síndrome serotoninérgico.","Falso: esa asociación prolonga el intervalo QT."]],
  "179": ["¿Qué interacción expone a una depresión respiratoria?",["Opioide junto con una benzodiacepina","Antiinflamatorio junto con un bloqueante del sistema renina","Tramadol junto con un antidepresivo serotoninérgico","Metadona junto con un antidepresivo serotoninérgico"],["Correcto: esta asociación es especialmente temida.","Falso: esa asociación amenaza la función renal.","Falso: esa asociación expone al síndrome serotoninérgico.","Falso: esa asociación prolonga el intervalo QT."]],
  "180": ["¿Qué precaución hay que tomar antes de una sesión de diatermia o de ultrasonidos?",["Retirar los parches y las cremas","Aplicar la crema justo antes de la sesión","Duplicar la dosis del parche colocado","No hace falta ninguna precaución"],["Correcto: sus componentes metálicos exponen a quemaduras.","Falso: esa conducta aumenta el riesgo de quemadura.","Falso: esa conducta es peligrosa.","Falso: el riesgo de quemadura es real y está documentado."]],
  "181": ["¿Qué hay que enseñar al paciente a distinguir en la sesión?",["El dolor de adaptación del dolor de alarma","El dolor agudo del dolor crónico","El dolor local del dolor irradiado","El dolor matutino del dolor vespertino"],["Correcto: esta distinción determina si se continúa o se detiene el ejercicio.","Falso: no es esa la distinción temporal que se busca aquí.","Falso: no es esa la distinción que se enseña en la sesión.","Falso: no es esa la distinción horaria descrita."]],
  "182": ["¿Por qué no hay que cargar un segmento anestesiado?",["La analgesia oculta los límites mecánicos","Porque la anestesia debilita el músculo","Porque la anestesia fragiliza los ligamentos","La anestesia retrasa la cicatrización local"],["Correcto: el paciente ya no percibe la señal que le haría detenerse.","Falso: no es esa la razón que se invoca.","Falso: no está en juego ninguna fragilización tisular.","Falso: no es ese el motivo de esta precaución."]],
  "183": ["¿Qué beneficio se espera de una infiltración epidural en una radiculopatía aguda?",["Un beneficio modesto, una ventana para la rehabilitación","Un beneficio duradero, que evita la rehabilitación","Una curación definitiva de la hernia discal","Una prevención de cualquier recidiva posterior"],["Correcto: asocia un anestésico y un corticoide.","Falso: el efecto es, al contrario, limitado en el tiempo.","Falso: el procedimiento no trata la hernia en sí.","Falso: no se obtiene ninguna prevención de ese tipo."]],
  "184": ["¿Qué condición precede a una radiofrecuencia de los ramos mediales?",["Un bloqueo diagnóstico claramente positivo","Una imagen que muestre artrosis facetaria","El fracaso de tres meses de fisioterapia","Un dolor de más de un año de evolución"],["Correcto: sin esa selección, el procedimiento no está justificado.","Falso: la imagen por sí sola no basta para seleccionar.","Falso: no es ese el criterio decisivo establecido.","Falso: la duración por sí sola no justifica el procedimiento."]],
  "185": ["¿Qué alivio cabe esperar de una radiofrecuencia en un paciente bien seleccionado?",["De seis a doce meses","De dos a cuatro semanas","De dos a tres años","Un alivio definitivo y permanente"],["Correcto: este beneficio exige un bloqueo diagnóstico previo claramente positivo.","Falso: ese plazo subestima el beneficio esperado.","Falso: esa duración está sobrestimada.","Falso: la regeneración nerviosa limita la duración del efecto."]],
  "186": ["¿Qué bloqueo se propone ante un hombro doloroso refractario?",["El bloqueo del nervio supraescapular","El bloqueo de los ramos mediales lumbares","El bloqueo del plexo lumbar","El bloqueo epidural torácico"],["Correcto: se inscribe en el abordaje intervencionista multimodal.","Falso: ese bloqueo corresponde al dolor facetario del raquis.","Falso: no afecta al hombro.","Falso: no es ese el procedimiento que se propone aquí."]],
  "187": ["¿Qué frecuencia de estimulación magnética se emplea sobre la corteza motora?",["Una frecuencia alta, de cinco a diez hercios","Una frecuencia baja, de un hercio","Una frecuencia de cien hercios","Una estimulación continua, sin frecuencia"],["Correcto: se dirige a la corteza motora primaria contralateral al dolor.","Falso: la frecuencia baja es inhibidora y no se emplea aquí.","Falso: esa frecuencia excede los protocolos descritos.","Falso: la estimulación magnética es pulsada por naturaleza."]],
  "188": ["¿Qué diana se elige en estimulación magnética si hay una depresión asociada?",["La corteza prefrontal dorsolateral","La corteza motora primaria contralateral","La corteza somatosensorial primaria","La corteza cingulada anterior"],["Correcto: se le aplican diez hercios, mientras que la diana analgésica es la corteza motora primaria.","Falso: es la diana analgésica, no la de la depresión asociada.","Falso: esa área no es una diana de estimulación.","Falso: no es accesible con esta técnica."]],
  "189": ["¿Qué contraindicación tiene la estimulación magnética transcraneal?",["Epilepsia no controlada o implante metálico","Un dolor de más de seis meses de evolución","Un antecedente de cirugía de la columna","Tomar analgésicos del segundo escalón"],["Correcto: el protocolo consta de diez a veinte sesiones en dos a cuatro semanas.","Falso: la cronicidad es, al contrario, una indicación.","Falso: ese antecedente no es una contraindicación.","Falso: el tratamiento en curso no es una contraindicación."]],
  "190": ["¿Cuáles son los seis procesos de la terapia de aceptación y compromiso?",["Aceptación, defusión, yo observador, presente, valores y acción","Rumiación, magnificación, indefensión, miedo, evitación y discapacidad","Seguridad, confianza, colaboración, autonomía, elección y consideración","Identidad, causa, consecuencia, cronología, control y curación"],["Correcto: este enfoque resulta especialmente adecuado ante la evitación rígida.","Falso: esos conceptos pertenecen al catastrofismo y al modelo de miedo-evitación.","Falso: esos principios pertenecen a la atención informada sobre el trauma.","Falso: esas dimensiones pertenecen al modelo del sentido común."]],
  "191": ["¿Qué enfoque psicológico conviene ante un catastrofismo con miedo al movimiento?",["La terapia cognitivo-conductual","La terapia de aceptación y compromiso","El mindfulness","La hipnosis conversacional"],["Correcto: la evitación rígida orienta más bien hacia la aceptación y el compromiso.","Falso: resulta más adecuada ante la evitación rígida.","Falso: se dirige más bien al estrés, al insomnio y a la rumiación.","Falso: no se propone en esta matriz de elección."]],
  "192": ["¿Qué enfoque conviene ante un estrés con insomnio y rumiación?",["El mindfulness","La terapia cognitivo-conductual","La terapia de aceptación y compromiso","Solo la educación en neurociencia"],["Correcto: la terapia cognitivo-conductual se dirige más bien al catastrofismo y al miedo.","Falso: se dirige sobre todo al catastrofismo y a la kinesiofobia.","Falso: se dirige más bien a la evitación rígida.","Falso: no basta en esta situación."]],
  "193": ["¿En qué pone el acento el mindfulness?",["En la curiosidad, y no en la relajación","En la relajación muscular profunda","En la supresión de los pensamientos negativos","En la confrontación progresiva con el movimiento"],["Correcto: aumenta la variabilidad cardíaca y reduce la reactividad amigdalina.","Falso: ese es precisamente el malentendido que hay que evitar.","Falso: el enfoque no busca suprimir los pensamientos.","Falso: esa estrategia pertenece a la exposición gradual."]],
  "194": ["¿Qué fenómeno sináptico constituye el objetivo terapéutico en el dolor persistente?",["La depresión a largo plazo","La potenciación a largo plazo","La sumación temporal de los impulsos","La inhibición presináptica puntual"],["Correcto: desensibiliza, mientras que la potenciación a largo plazo amplifica el dolor.","Falso: aumenta la eficacia sináptica y amplifica el dolor.","Falso: ese fenómeno participa en el wind-up.","Falso: no es ese el objetivo descrito."]],
  "195": ["¿Qué parámetros favorecen la depresión a largo plazo en neuromodulación percutánea?",["Intensidad baja o moderada y frecuencia baja","Intensidad máxima y frecuencia alta","Intensidad máxima e impulsos muy breves","Intensidad dolorosa y frecuencia variable"],["Correcto: los impulsos son largos y se mantiene un nivel poco doloroso.","Falso: esos parámetros favorecen, al contrario, la potenciación.","Falso: esos parámetros no corresponden al protocolo buscado.","Falso: mantenerse en un nivel poco doloroso forma parte del protocolo."]],
  "196": ["¿Por qué mecanismo produce el ejercicio una analgesia?",["Por las vías inhibidoras descendentes","Por un bloqueo directo de los nociceptores","Por una vasoconstricción de los tejidos dolorosos","Por un descenso de la temperatura local"],["Correcto: aumenta las endorfinas, los endocannabinoides, la serotonina y la noradrenalina.","Falso: el ejercicio no actúa directamente sobre los receptores periféricos.","Falso: no es ese el mecanismo descrito.","Falso: el ejercicio eleva, al contrario, la temperatura."]],
  "197": ["¿Qué efecto cerebral produce el ejercicio?",["Reduce la amígdala y aumenta la corteza prefrontal","Aumenta la amígdala y reduce la corteza prefrontal","No tiene ningún efecto sobre la actividad cerebral","Aumenta la excitabilidad del asta dorsal"],["Correcto: también disminuye la excitabilidad del asta dorsal.","Falso: los efectos son exactamente los inversos.","Falso: sus efectos centrales están bien documentados.","Falso: al contrario, la disminuye."]],
  "198": ["¿Qué caracteriza a la estimulación transcraneal por corriente directa?",["No genera potenciales de acción","Genera potenciales de acción repetidos","Utiliza un campo magnético pulsado","Actúa únicamente en la periferia"],["Correcto: solo modifica la excitabilidad: el ánodo la aumenta y el cátodo la reduce.","Falso: es precisamente lo que no hace.","Falso: esa descripción corresponde a la estimulación magnética.","Falso: sus dianas son corticales."]],
  "199": ["¿Cuál es el efecto del ánodo en la estimulación transcraneal por corriente directa?",["Aumenta la excitabilidad cortical","Disminuye la excitabilidad cortical","Desencadena potenciales de acción","No tiene ningún efecto sobre la excitabilidad"],["Correcto: el cátodo produce el efecto contrario, y las dianas son la corteza motora y la prefrontal.","Falso: ese efecto corresponde al cátodo.","Falso: la técnica no genera potenciales de acción.","Falso: la modulación de la excitabilidad es su principio mismo."]]
});
